/**
 * Phalita — Geographical Coordinates & Comprehensive Indian / Global Locations Database
 * A curated set of Indian cities, Assam towns & pilgrimage tirthas, plus world
 * hubs. Backed at runtime by a full GeoNames-derived index (city-index.ts).
 */

export interface LocationInfo {
  name: string;
  stateOrRegion?: string;
  country: string;
  latitude: number; // Decimal degrees, North is +, South is -
  longitude: number; // Decimal degrees, East is +, West is -
  timezoneOffsetHours: number; // Default civil timezone offset
  timezoneName: string;
  elevationMeters?: number;
}

export type CityLocation = LocationInfo;

