/**
 * Searches the location database by query string (case-insensitive substring match).
 */
export function searchLocations(query: string): LocationInfo[] {
  if (!query || query.trim().length === 0) return CITIES_DATABASE.slice(0, 15);
  const q = query.toLowerCase().trim();
  const indexed = searchIndexedCities(q, 40);
  if (indexed.length > 0) return indexed;
  return CITIES_DATABASE.filter(
    (c) =>
      c.name.toLowerCase().includes(q) ||
      c.country.toLowerCase().includes(q)
  );
}

/**
 * Converts DMS (Degrees, Minutes, Seconds) coordinate strings to decimal degrees.
 */
export function parseDMS(
  degrees: number,
  minutes: number,
  seconds: number,
  direction: 'N' | 'S' | 'E' | 'W'
): number {
  let dec = Math.abs(degrees) + minutes / 60.0 + seconds / 3600.0;
  if (direction === 'S' || direction === 'W') {
    dec = -dec;
  }
  return dec;
}

/**
 * Converts decimal degrees to formatted DMS string (e.g. 28°36′50″ N).
 */
export function formatDMS(decDeg: number, isLatitude: boolean): string {
  const abs = Math.abs(decDeg);
  const d = Math.floor(abs);
  const remM = (abs - d) * 60;
  const m = Math.floor(remM);
  const s = Math.round((remM - m) * 60);

  let dir = '';
  if (isLatitude) {
    dir = decDeg >= 0 ? 'N' : 'S';
  } else {
    dir = decDeg >= 0 ? 'E' : 'W';
  }

  return `${d}°${m.toString().padStart(2, '0')}′${s.toString().padStart(2, '0')}″ ${dir}`;
}

/**
 * Computes Local Mean Time (LMT) offset from longitude.
 * 1 degree of longitude = 4 minutes of time (1/15 hour).
 */
export function calculateLMTOffsetHours(longitudeDeg: number): number {
  return longitudeDeg / 15.0;
}
